/// the current area's world track.
fn play_music(h: &mut MgHost, vm: &mut V) -> R {
    let ty = vm.a(1);
    let name = if ty == 1 {
        "world".to_string()
    } else {
        let table = vm.img.addr("kMusicFilenames").unwrap_or(0);
