/// `speed_walk` of the character's bestiary entry (`CharacterState::Initialize` stores it at +0x1c).
fn walk_speed(&self) -> f32 {
    self.db
        .find_collection("bestiary", "base")
        .and_then(|c| self.db.attribute(c, "speed_walk"))
        .and_then(|v| v.as_f64())
        .map(|v| v as f32)
        .unwrap_or(2.5)
}

